create or replace view public.camera_country_coverage with (security_invoker=true) as select country_code,count(*)::int as total,count(*) filter(where record_type='speed_camera')::int as speed_cameras,count(*) filter(where record_type='red_light')::int as red_light_cameras,count(*) filter(where record_type='average_speed_section')::int as average_speed_sections,count(*) filter(where record_type='checkpoint')::int as checkpoints from public.camera_records where active and confidence in ('high','medium') group by country_code;
grant select on public.camera_country_coverage to anon,authenticated,camera_bootstrap;
